'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var roundsdf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof roundsdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v;

	v = roundsdf( NaN, 2 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = roundsdf( 3.14, NaN );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = roundsdf( NaN, NaN );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `NaN` if provided `n < 1`', function test( t ) {
	var v;

	v = roundsdf( 3.14, 0 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = roundsdf( 3.14, -1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `NaN` if provided a base less than 1', function test( t ) {
	var v;

	v = roundsdf( 3.14, 2, 0 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = roundsdf( 3.14, 2, -1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var v = roundsdf( PINF, 3 );
	t.strictEqual( v, PINF, 'returns +infinity' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var v = roundsdf( NINF, 3 );
	t.strictEqual( v, NINF, 'returns -infinity' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var v = roundsdf( 0.0, 2 );
	t.strictEqual( isPositiveZero( v ), true, 'returns +0' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var v = roundsdf( -0.0, 2 );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0' );
	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures', function test( t ) {
	t.strictEqual( roundsdf( 3.141592653589793, 1 ), 4.0, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 2 ), 3.2, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 3 ), 3.15, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 4 ), 3.142, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 5 ), 3.1416, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding large positive values', function test( t ) {
	t.strictEqual( roundsdf( 12368.0, 1 ), 20000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 2 ), 13000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 3 ), 12400.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding negative values', function test( t ) {
	t.strictEqual( roundsdf( -3.141592653589793, 1 ), -3.0, 'returns expected value' );
	t.strictEqual( roundsdf( -3.141592653589793, 3 ), -3.14, 'returns expected value' );
	t.strictEqual( roundsdf( -12368.0, 2 ), -12000.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding using a custom base', function test( t ) {
	var expected;
	var delta;
	var tol;
	var v;

	v = roundsdf( 0.0313, 2, 2 );
	expected = 0.03125;

	if ( v === expected ) {
		t.strictEqual( v, expected, 'returns expected value' );
	} else {
		delta = abs( v - expected );
		tol = 1.0 * EPS * abs( expected );
		t.ok( delta <= tol, 'within tolerance. v: '+v+'. expected: '+expected+'. delta: '+delta+'. tol: '+tol+'.' );
	}

	t.end();
});

tape( 'the function rounds toward positive infinity', function test( t ) {
	t.strictEqual( roundsdf( 3.14, 1 ), 4.0, 'returns expected value' );
	t.strictEqual( roundsdf( -3.14, 1 ), -3.0, 'returns expected value' );
	t.strictEqual( roundsdf( 9.5, 1 ), 10.0, 'returns expected value' );
	t.strictEqual( roundsdf( 9.4, 1 ), 10.0, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0, 2 ), 0.0, 'returns expected value' );
	t.strictEqual( roundsdf( -0.0, 2 ), -0.0, 'returns expected value' );
	t.end();
});
